#include "xprim_geom_material_ball_data.h"

namespace xprim_geom::material_ball
{
    //-----------------------------------------------------------------------------
    // The material preview mesh (a shader ball), centred on 0, its largest side Size. Its data is generated by tools/obj_to_xprim.
    inline
    mesh Generate( float Size = 1.0f ) noexcept
    {
        using namespace data;
        constexpr int   nValues = 12;
        constexpr auto  nVerts  = std::size(vertices_v) / nValues;
        const auto      U       = [](std::uint16_t q) { return q / 65535.0f; };
        const auto      S       = [](std::uint16_t q) { return std::int16_t(q) / 32767.0f; };

        mesh Mesh;
        Mesh.m_Vertices.reserve(nVerts);
        for( std::size_t i = 0; i < nVerts; ++i )
        {
            const auto* p = &vertices_v[i * nValues];
            Mesh.m_Vertices.push_back
            ( vertex
            { .m_Position = float3{ (U(p[0]) - 0.5f) * box_v[0], (U(p[1]) - 0.5f) * box_v[1], (U(p[2]) - 0.5f) * box_v[2] } * Size
            , .m_Normal   = float3{ S(p[3]), S(p[4]), S(p[5]) }.Normalize()
            , .m_Tangent  = { S(p[6]), S(p[7]), S(p[8]), p[9] ? 1.0f : -1.0f }
            , .m_Texcoord = { uv_lo_v[0] + U(p[10]) * (uv_hi_v[0] - uv_lo_v[0]), uv_lo_v[1] + U(p[11]) * (uv_hi_v[1] - uv_lo_v[1]) }
            });
        }
        Mesh.m_Indices.assign(std::begin(indices_v), std::end(indices_v));
        return Mesh;
    }
}
